<section class="bg-gradient-to-br from-cyan-950/70 to-slate-900 border border-cyan-900 rounded-xl p-5"><div class="flex justify-between items-start"><div><h2 class="text-xl font-bold">Watch Folders</h2><p class="text-slate-400 text-sm">OrionX revisa automáticamente cada carpeta e importa únicamente archivos nuevos.</p></div><span class="bg-cyan-500/15 text-cyan-300 px-3 py-1 rounded-full text-xs">Automático</span></div>
<form method="post" action="/libraries/watch" class="grid md:grid-cols-5 gap-3 mt-5"><?=$csrf->field()?><input required name="name" placeholder="Nombre: Películas 4K" class="bg-slate-800 p-2 rounded"><select name="content_type" class="bg-slate-800 p-2 rounded"><option value="movie">Películas</option><option value="series">Series y episodios</option></select><input required name="path" placeholder="/mnt/media/movies" class="bg-slate-800 p-2 rounded"><select name="server_id" class="bg-slate-800 p-2 rounded"><option value="">Servidor principal</option><?php foreach($servers as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach?></select><div class="flex gap-2"><input type="number" min="1" max="1440" name="interval_minutes" value="10" class="w-20 bg-slate-800 p-2 rounded" title="Minutos"><button class="flex-1 bg-cyan-700 px-3 rounded">Vigilar</button></div></form>
<div class="grid lg:grid-cols-2 gap-3 mt-5"><?php foreach($watchFolders as $w):?><article class="bg-slate-900/80 border border-slate-700 rounded-lg p-4"><div class="flex justify-between"><div><strong><?=htmlspecialchars($w['name'])?></strong><div class="text-xs text-slate-400 break-all"><?=htmlspecialchars($w['mount_path'])?></div></div><span class="<?=$w['active']?'text-emerald-400':'text-slate-500'?>"><?=$w['content_type']==='movie'?'Películas':'Series'?></span></div><div class="flex items-center justify-between mt-3 text-xs text-slate-400"><span><?=htmlspecialchars($w['server_name']??'Principal')?> · cada <?=$w['interval_minutes']?> min</span><span>Último: <?=htmlspecialchars($w['last_status'])?></span></div><?php if($w['active']):?><div class="flex gap-2 mt-3"><form method="post" action="/libraries/watch/run"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$w['id']?>"><button class="bg-emerald-700 px-3 py-1.5 rounded">Escanear ahora</button></form><form method="post" action="/libraries/watch/disable" onsubmit="return confirm('¿Desactivar la vigilancia de esta carpeta?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$w['id']?>"><button class="bg-slate-700 px-3 py-1.5 rounded">Desactivar</button></form></div><?php endif?></article><?php endforeach?><?php if(!$watchFolders):?><p class="lg:col-span-2 text-center text-slate-500 py-5">Todavía no hay carpetas vigiladas.</p><?php endif?></div></section>
